from pathlib import Path
import subprocess,json,hashlib,gzip,datetime
out=Path(__file__).resolve().parents[1];root=Path.cwd();b=json.load(gzip.open(out/'before.json.gz'));sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();hashes={p:sha(p) for p in b['hashes']};src=out/'workers/source_lines.rs';lib=root/'target/debug/libtypst_core.rlib';binary=Path('/tmp/tekt-source-lines');cmd=['rustc','--edition=2021',str(src),'-L','dependency='+str(root/'target/debug/deps'),'--extern','typst_core='+str(lib),'-o',str(binary)];record={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'head':b['head'],'source_hashes':hashes,'source_sha256':sha(src),'library_sha256':sha(lib),'command':cmd};r=subprocess.run(cmd,capture_output=True,text=True);record.update(build_exit=r.returncode,stderr=r.stderr);(out/'source-lines-before.json').write_text(json.dumps(record,indent=2)+'\n');assert r.returncode==0,r.stderr;r=subprocess.run([str(binary)],capture_output=True,text=True);record.update(exit=r.returncode,stdout=r.stdout,stderr=r.stderr,binary_sha256=sha(binary),sources_unchanged=all(sha(p)==h for p,h in hashes.items()));(out/'source-lines-before.json').write_text(json.dumps(record,indent=2)+'\n');assert r.returncode==0 and record['sources_unchanged'];print(r.stdout,flush=True)
